using TMPro;
using UnityEngine;
using UnityEngine.UI;

public class StatsManager : MonoBehaviour
{
    public static StatsManager Instance { get; private set; }
    private Transform MainPanel;
    public GameObject PopupStatsPanelPrefab;
    private void Awake()
    {
        // Ensure there's only one instance of PanelManager
        if (Instance == null)
        {
            Instance = this;
            // DontDestroyOnLoad(gameObject); // Keep this object across scenes
        }
        else
        {
            Destroy(gameObject); // Destroy duplicate instances
        }
    }
    void Start()
    {
        Initialize();
    }
    public void Initialize()
    {
        MainPanel = UIManager.Instance.GetTransform(AppConstants.Transform.MAIN_PANEL);
        PopupStatsPanelPrefab = UIManager.Instance.Get(AppConstants.Prefab.General.POPUP_STATS_PANEL_PREFAB);
    }
    public void CreateStatsManager(IStats stat)
    {
        GameObject gameObject = Instantiate(PopupStatsPanelPrefab, MainPanel);
        Transform popupTransform = gameObject.transform;

        // Cache lại Content Transform để tái sử dụng
        Transform contentTransform = popupTransform.Find("Scroll View/Viewport/Content");

        Button closeButton = popupTransform.Find("CloseButton").GetComponent<Button>();
        closeButton.onClick.AddListener(() =>
        {
            AudioManager.Instance.PlaySFX(AudioConstants.SFX.BUTTON_CLICK_SOUND);
            Destroy(gameObject);
        });

        TextMeshProUGUI titleText = popupTransform.Find("TitleText").GetComponent<TextMeshProUGUI>();
        titleText.text = LocalizationManager.Get(AppDisplayConstants.MainType.STATS);

        CreateStatsManager(stat, contentTransform);
    }

