    private void SetupStat(Transform contentTransform, string statObjectName, string statField, string statDisplayName, double value, bool isPercent = false)
    {
        // Tìm trực tiếp statObjectName từ Content, không cần đi qua Scroll View/Viewport nữa
        Transform statTransform = contentTransform.Find(statObjectName);

        if (statTransform == null)
        {
            Debug.LogWarning($"[SetupStat] Không tìm thấy stat object: {statObjectName}");
            return;
        }

        RawImage iconImage = statTransform.Find("IconImage").GetComponent<RawImage>();
        TextMeshProUGUI titleText = statTransform.Find("StatTitleText").GetComponent<TextMeshProUGUI>();
        TextMeshProUGUI valueText = statTransform.Find("StatText").GetComponent<TextMeshProUGUI>();

        TextureHelper.CreatePropertyRuneUI(statField, iconImage);

        titleText.text = LocalizationManager.Get(statDisplayName);
        titleText.enableWordWrapping = false;

        string formattedValue = NumberFormatterHelper.FormatNumberExtended(value, true);
        valueText.text = isPercent ? $"{formattedValue} %" : formattedValue;
    }
